function appendWebLinks(parent,text){const re=/https?:\/\/[^\s<>"']+|\[[^\]\n]+\]\(https?:\/\/[^\s<>]+\)/g;let last=0;for(const match of text.matchAll(re)){parent.append(document.createTextNode(text.slice(last,match.index)));let label=match[0],url=label,suffix='';const md=/^\[([^\]]+)\]\((.+)\)$/.exec(label);if(md){label=md[1];url=md[2];}else{url=url.replace(/[.,;:!?]+$/,'');while(url.endsWith(')')&&(url.match(/\)/g)||[]).length>(url.match(/\(/g)||[]).length)url=url.slice(0,-1);suffix=label.slice(url.length);label=url;}try{const parsed=new URL(url);if(!['http:','https:'].includes(parsed.protocol))throw Error();parent.append(el('a',{href:parsed.href,target:'_blank',rel:'noopener noreferrer'},label),document.createTextNode(suffix));}catch{parent.append(document.createTextNode(match[0]));}last=match.index+match[0].length;}parent.append(document.createTextNode(text.slice(last)));}
function appendLinks(parent,text,messageId){
 let end=0;for(const link of markdownLinks(text)){appendWebLinks(parent,text.slice(end,link.index));
 if(localFileTarget(link.target)&&messageId){const a=el('a',{href:'#file-preview',class:'file-preview-link'},link.label);a.addEventListener('click',event=>{event.preventDefault();void openFilePreview(messageId,link.target,link.label);});parent.append(a);}
 else if(/^https?:\/\//i.test(link.target))parent.append(el('a',{href:link.target,target:'_blank',rel:'noopener noreferrer'},link.label));
 else parent.append(document.createTextNode(link.label));end=link.index+link.length;
 }appendWebLinks(parent,text.slice(end));
}
let previewVersion=0,previewObjectURL=null;
async function openFilePreview(messageId,target,label){
 const version=++previewVersion,view=el('div',{class:'file-preview-content'});view.append(el('p',{role:'status'},t('Carregando prévia…')));openDialog(label,view);
 if(previewObjectURL){URL.revokeObjectURL(previewObjectURL);previewObjectURL=null;}
 try{const file=await api('file-preview',{messageId,target});if(version!==previewVersion)return;view.replaceChildren();
 let blob;if(file.text!==undefined){const pre=el('pre',{class:'file-preview-text'});pre.append(el('code',{},file.text));view.append(pre);blob=new Blob([file.text],{type:'text/plain;charset=utf-8'});}
 else{const bytes=Uint8Array.from(atob(file.data),c=>c.charCodeAt(0));blob=new Blob([bytes],{type:file.mime});}
 previewObjectURL=URL.createObjectURL(blob);const url=previewObjectURL;
 if(file.text===undefined){if(/^image\/(png|jpeg|gif|webp)$/.test(file.mime))view.append(el('img',{src:url,alt:file.name,class:'file-preview-image'}));else if(file.mime==='application/pdf')view.append(el('iframe',{src:url,title:file.name,class:'document-preview'}));else view.append(el('p',{},t('Este formato não tem prévia. Baixe o arquivo para abri-lo.')));}
 view.append(el('a',{href:url,download:file.name,class:'secondary'},t('Baixar arquivo')));
 }catch{if(version===previewVersion)view.replaceChildren(el('p',{role:'alert'},t('Não foi possível abrir este arquivo. Ele pode ter sido movido, estar fora do espaço do agente ou exceder o limite de 8 MB. Peça ao agente para anexá-lo novamente.')));}
}
$('#dialog').addEventListener('close',()=>{previewVersion++;if(previewObjectURL){URL.revokeObjectURL(previewObjectURL);previewObjectURL=null;}});
function richText(text,messageId){
 const box=el('div',{class:'message-text'});const parts=text.split(/(```[\s\S]*?```)/g);
 function inline(parent,line){for(const part of line.split(/(\*\*[^*]+\*\*|`[^`]+`)/g)){if(part.startsWith('**')&&part.endsWith('**'))parent.append(el('strong',{},part.slice(2,-2)));else if(part.startsWith('`')&&part.endsWith('`'))parent.append(el('code',{},part.slice(1,-1)));else appendLinks(parent,part,messageId);}}
 for(const part of parts){if(!part)continue;if(part.startsWith('```')){const pre=el('pre');pre.append(el('code',{},part.slice(3,-3).replace(/^\w*\n/,'')));box.append(pre);continue;}
 let list=null;for(const line of part.split('\n')){
 const bullet=line.match(/^\s*(?:[-*]|\d+\.)\s+(.+)/);
 if(bullet){if(!list){list=el(/^\s*\d/.test(line)?'ol':'ul');box.append(list);}const li=el('li');inline(li,bullet[1]);list.append(li);continue;}list=null;
 if(!line.trim())continue;const node=el(/^#{1,3}\s/.test(line)?'h3':'p');inline(node,line.replace(/^#{1,3}\s+/,''));box.append(node);
 }}return box;
}
